SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'v_rueck_a_min', 'Erforderliches Einstauvolumen Typ A: V_Rück = Q × 25 s (Gl. 1)', 'number', 'l', false, '§5.3.2, Gl. 1', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-02-D1 (Q × 25; Q = Volumenstrom der Zulaufleitung nach DIN EN 12056-3:2001-01 Tab. C.1 — externer Wert, bleibt Eingabe). Das vorhandene V_Rueck_A bleibt die eingetragene Ist-Größe; Ablösung der Gl. 1 (die heute in das Eingabefeld schreibt) STAGED (din1989_2-R-1).', 'imported_unverified', 'Bei Filtern des Typs A erfolgt eine mechanische Abtrennung der Fremdstoffe mit anschließender Sedimentation dieser Stoffe in einem ausreichend großen Volumen zur Aktivierung einer dauerhaft wirksamen Sedimentations- und/oder Rückhaltewirkung (siehe Bild 1). Die Filtereinheiten müssen vor den Trennflächen (bei senkrechter Anordnung) oder über den Trennflächen (bei waagrechter Anordnung) ein Einstauvolumen $V_{\text {Rück }}$ nach Gleichung 1 sicherstellen. Filter des Typs A dürfen sowohl innerhalb als auch außerhalb von Regenwasserspeichern angeordnet werden. — V_{\text {Rück }}=Q \times 25 \tag{1} — Q der Volumenstrom in der planmäßigen Zulaufleitung zum Filter bei einem Füllungsgrad von $70 \%$ und einem Gefälle von 1 \% nach DIN EN 12056-3:2001-01, Tabelle C.1, in Liter je Sekunde', 'derived', NULL, NULL, 'filtertyp == ''typ_a''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'v_rueck_a_min') AND w.code = 'DIN-1989-2-02' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'v_rueck_b_min', 'Erforderliches Volumen der herausnehmbaren Behältnisse Typ B: V_Rück = Q × 2 s (Gl. 2)', 'number', 'l', false, '§5.3.3, Gl. 2', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-02-D2 (Q × 2); das vorhandene V_Rueck_B bleibt die eingetragene Ist-Größe (Σ der Behältnisse → behaeltnis_volumen_sum); Ablösung der Gl. 2 STAGED (din1989_2-R-1).', 'imported_unverified', 'Das Volumen der herausnehmbaren Behältnisse $V_{\text {Rück }}$ muss mindestens betragen: — V_{\text {Rück }}=Q \times 2 \tag{2}', 'derived', NULL, NULL, 'filtertyp == ''typ_b''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'v_rueck_b_min') AND w.code = 'DIN-1989-2-02' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'behaeltnisse', 'Herausnehmbare Behältnisse (Typ B, §5.3.3)', 'json', NULL, false, '§5.3.3', 'Plan 3: Zeilen je herausnehmbarem Behältnis (Volumen, Masse gefüllt, Entnahmetiefe bei Erdeinbau); Σ Volumen → behaeltnis_volumen_sum (DIN-1989-2-02-D3), max. Masse → behaeltnis_masse_max (-D4), max. Tiefe → behaeltnis_grifftiefe_max (-D5); Ablösung der Skalare V_Rueck_B / behaeltnis_masse / tiefe_gok_griff und Umstellung von CR-04/05/06 STAGED (din1989_2-D-3 … D-5, G-2).', 'imported_unverified', 'Bei Filtern des Typs B erfolgt eine mechanische Abtrennung der Fremdstoffe mit anschließender Sedimentation dieser Stoffe durch eine zuverlässige und planmäßige Rückhaltewirkung, die durch die Anordnung von Behältnissen zur Sammlung der Fremdstoffe erzielt werden kann. Diese Behältnisse müssen ohne Verwendung von Werkzeugen leicht herausnehmbar und übersichtlich angeordnet sein. Die Fremdstoffe müssen vor dem Filterelement (zulaufseitig) gesammelt werden (siehe Bild 2). — Die Masse eines planmäßig herausnehmbaren Behältnisses darf im gefüllten Zustand 20 kg nicht überschreiten. — Bei Erdeinbau darf zwischen Geländeoberkante (Schachtabdeckung) und Entnahmeelement (z. B. Haltegriff) eine Tiefe von 60 cm nicht überschritten werden. — Das Volumen der herausnehmbaren Behältnisse $V_{\text {Rück }}$ muss mindestens betragen:', 'register', '{"title":"Herausnehmbare Behältnisse (Typ B)","subtitle":"§5.3.3 — je Behältnis Volumen, Masse gefüllt (≤ 20 kg) und bei Erdeinbau die Entnahmetiefe (≤ 60 cm)","add_label":"+ Behältnis","placement":"section","columns":[{"key":"label","label":"Bezeichnung","type":"text"},{"key":"volumen_l","label":"Volumen","type":"number","unit":"l","required":true,"min":0,"aria_label":"Volumen des Behältnisses"},{"key":"masse_gefuellt_kg","label":"Masse gefüllt","type":"number","unit":"kg","required":true,"min":0,"aria_label":"Masse des gefüllten Behältnisses"},{"key":"masse_ok","label":"≤ 20 kg","type":"derived","expr":"if(masse_gefuellt_kg <= 20, 1, 0)","display":"badge","value_labels":{"0":"> 20 kg","1":"≤ 20 kg"}},{"key":"grifftiefe_cm","label":"Tiefe GOK bis Entnahmeelement","type":"number","unit":"cm","min":0,"visible_when":"einbausystem == ''separat_erdeinbau''","aria_label":"Tiefe Geländeoberkante bis Entnahmeelement"},{"key":"grifftiefe_ok","label":"≤ 60 cm","type":"derived","expr":"if(grifftiefe_cm IS NULL, 1, if(grifftiefe_cm <= 60, 1, 0))","display":"badge","value_labels":{"0":"> 60 cm","1":"≤ 60 cm"}},{"key":"ohne_werkzeug","label":"ohne Werkzeug herausnehmbar","type":"boolean"}],"footer":["behaeltnis_volumen_sum","behaeltnis_masse_max","behaeltnis_grifftiefe_max"],"note":"Bei Filtern des Typs B erfolgt eine mechanische Abtrennung der Fremdstoffe mit anschließender Sedimentation dieser Stoffe durch eine zuverlässige und planmäßige Rückhaltewirkung, die durch die Anordnung von Behältnissen zur Sammlung der Fremdstoffe erzielt werden kann. Diese Behältnisse müssen ohne Verwendung von Werkzeugen leicht herausnehmbar und übersichtlich angeordnet sein. Die Fremdstoffe müssen vor dem Filterelement (zulaufseitig) gesammelt werden (siehe Bild 2). Die Masse eines planmäßig herausnehmbaren Behältnisses darf im gefüllten Zustand 20 kg nicht überschreiten. Bei Erdeinbau darf zwischen Geländeoberkante (Schachtabdeckung) und Entnahmeelement (z. B. Haltegriff) eine Tiefe von 60 cm nicht überschritten werden."}'::jsonb, NULL, 'filtertyp == ''typ_b''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'behaeltnisse') AND w.code = 'DIN-1989-2-02' AND s.code = 'DIN-1989-2';
