FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'behaeltnis_volumen_sum') AND w.code = 'DIN-1989-2-02' AND s.code = 'DIN-1989-2';
