SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'behaeltnis_masse_max', 'Größte Masse eines gefüllten Behältnisses (Grenze 20 kg)', 'number', 'kg', false, '§5.3.3', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-02-D4 (max_rows über behaeltnisse); Umstellung von CR-05 STAGED (din1989_2-G-2).', 'imported_unverified', 'Die Masse eines planmäßig herausnehmbaren Behältnisses darf im gefüllten Zustand 20 kg nicht überschreiten.', 'derived', NULL, NULL, 'filtertyp == ''typ_b''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'behaeltnis_masse_max') AND w.code = 'DIN-1989-2-02' AND s.code = 'DIN-1989-2';
