SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'behaeltnis_grifftiefe_max', 'Größte Tiefe GOK bis Entnahmeelement (Erdeinbau, Grenze 60 cm)', 'number', 'cm', false, '§5.3.3', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-02-D5 (max_rows über die eingetragenen Entnahmetiefen; ohne Eintrag offen); Umstellung von CR-06 STAGED (din1989_2-G-2).', 'imported_unverified', 'Bei Erdeinbau darf zwischen Geländeoberkante (Schachtabdeckung) und Entnahmeelement (z. B. Haltegriff) eine Tiefe von 60 cm nicht überschritten werden.', 'derived', NULL, NULL, 'filtertyp == ''typ_b'' AND einbausystem == ''separat_erdeinbau''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'behaeltnis_grifftiefe_max') AND w.code = 'DIN-1989-2-02' AND s.code = 'DIN-1989-2';
