INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'einbau_fallrohr', 'Einbau in ein Fallrohr vorgesehen', 'boolean', NULL, false, '§5.2.3', 'Plan 3: Treiber der Temperaturbeständigkeits-Anforderung (-20 °C bis +80 °C gilt nur für den Einbau in Fallrohre).', 'imported_unverified', 'Für den Einbau in Fallrohre muss der Werkstoff zwischen $-20^{\circ} \mathrm{C}$ und $+80^{\circ} \mathrm{C}$ temperaturbeständig sein.', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
