INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'prueflaeufe', 'Prüfläufe hydraulischer Wirkungsgrad (Tab. 2, Gl. 3 / Gl. 5)', 'json', NULL, false, '§6.4.5, §6.4.6, Tab. 2', 'Plan 3: Zeilen je Prüfstufe (Tab. 2 → % und Prüfzeit gefüllt, Q_Zu / Q_Ab gemessen, unbelastet oder dauerbelastet); η je Zeile nach Gl. 3 / Gl. 5; Ausgaben eta_hydr_unbel_p100 / _min und eta_hydr_bel_p100 / _min (DIN-1989-2-03-D6 … D9); Ablösung der Skalare Q_Zu / Q_Ab / eta_hydr / eta_hyd_bel STAGED (din1989_2-D-6 … D-9, R-4).', 'imported_unverified', 'Als Prüfmedium ist Klarwasser zu verwenden. Das unbelastete Filtersystem wird über die vorgegebene Nennweite des Zulaufquerschnitts, Gefälle $l=1 / 100$ nach DIN EN 12056-3:2001-01, Tabelle C. 1 mit in Tabelle 2 angegebenen Volumenströmen über eine jeweils festgelegte Dauer angeströmt. Anströmungen des Filters mit geringeren Volumenströmen sind über längere Zeit ( 4 min bzw. 8 min ) aufrecht zu erhalten, um bei der Füllstandsmessung im Auffangbehälter eine höhere Genauigkeit zu erzielen. — Tabelle 2 - Prüfzeiten für Volumenströme — \eta_{\mathrm{hydr}}=\frac{Q_{\mathrm{Zu}}-Q_{\mathrm{Ab}}}{Q_{\mathrm{Zu}}} \tag{3} — Abschließend ist der hydraulische Wirkungsgrad des verschmutzten Systems mit Klarwasser unter Einhaltung der Volumenströme und der Dauer nach 6.4.5 zu ermitteln. — \eta_{\text {hyd,bel }}=\frac{Q_{\mathrm{Zu}}-Q_{\mathrm{Ab}}}{Q_{\mathrm{Zu}}} \tag{5}', 'register', '{"title":"Prüfläufe hydraulischer Wirkungsgrad (Tab. 2)","subtitle":"§6.4.5 / §6.4.6 — je Stufe Q_Zu/Q_Zu,max, Prüfzeit t, gemessene Q_Zu und Q_Ab; η je Zeile nach Gl. 3 / Gl. 5","add_label":"+ Prüflauf","placement":"section","columns":[{"key":"stufe","label":"Stufe Q_Zu/Q_Zu,max (Tab. 2)","type":"lookup_key","required":true,"lookup":{"table_code":"TAB2"}},{"key":"q_pct","label":"%","type":"lookup_value","unit":"%","lookup":{"table_code":"TAB2","key_column":"stufe","value":"q_pct"}},{"key":"t_min","label":"Prüfzeit t (Tab. 2)","type":"lookup_value","unit":"min","lookup":{"table_code":"TAB2","key_column":"stufe","value":"pruefzeit_min"}},{"key":"q_soll","label":"Q_Zu Soll","type":"derived","expr":"Q_Zu_max * q_pct / 100","unit":"l/s"},{"key":"belastet","label":"dauerbelastet (6.4.6)","type":"boolean"},{"key":"q_zu","label":"Q_Zu gemessen","type":"number","unit":"l/s","required":true,"min":0,"aria_label":"zugeführter Volumenstrom Q_Zu"},{"key":"q_ab","label":"Q_Ab gemessen","type":"number","unit":"l/s","required":true,"min":0,"aria_label":"abgeführter Volumenstrom Q_Ab"},{"key":"eta_row","label":"η = (Q_Zu − Q_Ab) / Q_Zu","type":"derived","expr":"(q_zu - q_ab) / q_zu"}],"footer":["prueflaeufe_count","eta_hydr_unbel_p100","eta_hydr_unbel_min","eta_hydr_bel_p100","eta_hydr_bel_min"],"note":"Als Prüfmedium ist Klarwasser zu verwenden. Das unbelastete Filtersystem wird über die vorgegebene Nennweite des Zulaufquerschnitts, Gefälle $l=1 / 100$ nach DIN EN 12056-3:2001-01, Tabelle C. 1 mit in Tabelle 2 angegebenen Volumenströmen über eine jeweils festgelegte Dauer angeströmt. Anströmungen des Filters mit geringeren Volumenströmen sind über längere Zeit ( 4 min bzw. 8 min ) aufrecht zu erhalten, um bei der Füllstandsmessung im Auffangbehälter eine höhere Genauigkeit zu erzielen. Abschließend ist der hydraulische Wirkungsgrad des verschmutzten Systems mit Klarwasser unter Einhaltung der Volumenströme und der Dauer nach 6.4.5 zu ermitteln. Welche Stufe den dokumentierten Wirkungsgrad liefert, nennt der Text nicht (din1989_2-J-2): ausgegeben werden die Stufe 100 % (Bezugsgröße Q_max, §5.4.2) und das Minimum der Kurve (Bild E.1)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'prueflaeufe') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'prueflaeufe_count', 'Anzahl erfasster Prüfläufe (Tab. 2 druckt 7 Stufen je Zustand)', 'number', NULL, false, '§6.4.5, Tab. 2', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D5 (count_rows über prueflaeufe).', 'imported_unverified', 'Als Prüfmedium ist Klarwasser zu verwenden. Das unbelastete Filtersystem wird über die vorgegebene Nennweite des Zulaufquerschnitts, Gefälle $l=1 / 100$ nach DIN EN 12056-3:2001-01, Tabelle C. 1 mit in Tabelle 2 angegebenen Volumenströmen über eine jeweils festgelegte Dauer angeströmt. Anströmungen des Filters mit geringeren Volumenströmen sind über längere Zeit ( 4 min bzw. 8 min ) aufrecht zu erhalten, um bei der Füllstandsmessung im Auffangbehälter eine höhere Genauigkeit zu erzielen.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'prueflaeufe_count') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'eta_hydr_unbel_p100', 'η_hydr unbelastet bei 100 % Q_Zu,max (Gl. 3)', 'number', NULL, false, '§5.4.2, §6.4.5, Gl. 3', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D6 (η der Zeile Stufe 100 %, unbelastet; Bezugsgröße Q_max nach §5.4.2 — welche Stufe dokumentiert wird, ist din1989_2-J-2); Zwilling zu eta_hydr (Gl. 3) und eta_hydr_unbel_doku (-02).', 'imported_unverified', 'Bezugsgröße ist der maximal zufließende Volumenstrom $Q_{\text {max }}$, nach DIN EN 12056-3:2001-01, Tabelle C. 1 in Abhängigkeit von der Nennweite DN der Zulaufleitung bei $1 \%$ Gefälle (70 \% Füllungsgrad). — \eta_{\mathrm{hydr}}=\frac{Q_{\mathrm{Zu}}-Q_{\mathrm{Ab}}}{Q_{\mathrm{Zu}}} \tag{3}', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'eta_hydr_unbel_p100') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'eta_hydr_unbel_min', 'η_hydr unbelastet — Minimum über alle Stufen (Bild E.1)', 'number', NULL, false, '§6.4.5, Gl. 3, Anhang E', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D8 (min_rows über die unbelasteten Zeilen — die sichere Seite der η-Kurve; din1989_2-J-2).', 'imported_unverified', '\eta_{\mathrm{hydr}}=\frac{Q_{\mathrm{Zu}}-Q_{\mathrm{Ab}}}{Q_{\mathrm{Zu}}} \tag{3}', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'eta_hydr_unbel_min') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'eta_hydr_bel_p100', 'η_hyd,bel dauerbelastet bei 100 % Q_Zu,max (Gl. 5)', 'number', NULL, false, '§5.4.3, §6.4.6, Gl. 5', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D7 (η der Zeile Stufe 100 %, dauerbelastet); nur für DN ≤ 200 (§5.4.3); Zwilling zu eta_hyd_bel (Gl. 5) und eta_hydr_bel_doku (-02).', 'imported_unverified', 'Um Rückschlüsse auf die Dauerhaftigkeit und die Betriebssicherheit des Filtersystems zu ermöglichen, ist für Filter mit Zulaufnennweiten $\leq$ DN 200 der hydraulische Wirkungsgrad des belasteten Filters nach 6.4.6 zu ermitteln und in der Produktdokumentation anzugeben. — Abschließend ist der hydraulische Wirkungsgrad des verschmutzten Systems mit Klarwasser unter Einhaltung der Volumenströme und der Dauer nach 6.4.5 zu ermitteln. — \eta_{\text {hyd,bel }}=\frac{Q_{\mathrm{Zu}}-Q_{\mathrm{Ab}}}{Q_{\mathrm{Zu}}} \tag{5}', 'derived', NULL, NULL, 'DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'eta_hydr_bel_p100') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'eta_hydr_bel_min', 'η_hyd,bel dauerbelastet — Minimum über alle Stufen (Bild E.1)', 'number', NULL, false, '§6.4.6, Gl. 5, Anhang E', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D9 (min_rows über die dauerbelasteten Zeilen); nur für DN ≤ 200.', 'imported_unverified', 'Um Rückschlüsse auf die Dauerhaftigkeit und die Betriebssicherheit des Filtersystems zu ermöglichen, ist für Filter mit Zulaufnennweiten $\leq$ DN 200 der hydraulische Wirkungsgrad des belasteten Filters nach 6.4.6 zu ermitteln und in der Produktdokumentation anzugeben. — \eta_{\text {hyd,bel }}=\frac{Q_{\mathrm{Zu}}-Q_{\mathrm{Ab}}}{Q_{\mathrm{Zu}}} \tag{5}', 'derived', NULL, NULL, 'DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'eta_hydr_bel_min') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'v_pruef_leist_min', 'Mindestvolumen Vorlagebehälter Leistungsfähigkeit: Q_Zu,max × 90 s (Gl. 4)', 'number', 'l', false, '§6.4.6, Gl. 4', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D1 (Q_Zu_max × 90); das vorhandene V_Pruef_leist bleibt das eingetragene Ist-Volumen — Gl. 4 druckt eine Ungleichung, die Prüfung ist v_pruef_leist_ok (-D3); Ablösung der Gl. 4 STAGED (din1989_2-R-3).', 'imported_unverified', 'Als Prüfmedium ist Klarwasser zu verwenden, dem sedimentierbare Stoffe, Schwebstoffe und Schwimmstoffe nach 6.5.1 und Tabelle 3 hinzugefügt sind. Der Vorlagebehälter muss mindestens einem Volumen $V_{\text {Prüf }}$ entsprechen, das dem maximalen Volumenstrom $Q_{\mathrm{Zu}, \max }$ der jeweils vorgegebenen Nennweite des Querschnittes der Zulaufleitung bei $1 \%$ Gefälle, multipliziert mit 90 s entspricht. — V_{\text {Prüf }} \geq Q_{\mathrm{Zu}, \max } \times 90 \tag{4}', 'derived', NULL, NULL, 'DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'v_pruef_leist_min') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'v_pruef_trenn_min', 'Mindestvolumen Vorlagebehälter Trennwirkung: Q_Zu,max × 180 s (Gl. 6)', 'number', 'l', false, '§6.5.1, Gl. 6', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D2 (Q_Zu_max × 180); V_Pruef_trenn bleibt das Ist-Volumen; Prüfung v_pruef_trenn_ok (-D4); Ablösung der Gl. 6 STAGED (din1989_2-R-3).', 'imported_unverified', 'Der Vorlagebehälter muss mindestens einem Volumen $V_{\text {Prüf }}$ entsprechen, das dem maximalen Volumenstrom $Q_{\text {Zu, max }}$ der jeweils vorgegebenen Nennweite des Querschnittes der Zulaufleitung bei $1 \%$ Gefälle, multipliziert mit 180 s entspricht (Gleichung (6)). — V_{\text {Prüf }} \geq Q_{\text {Zu,max }} \times 180 \tag{6}', 'derived', NULL, NULL, 'DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'v_pruef_trenn_min') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'v_pruef_leist_ok', 'V_Prüf (Leistungsfähigkeit) ≥ Q_Zu,max × 90 (1 = erfüllt, 0 = unterschritten)', 'number', NULL, false, '§6.4.6, Gl. 4', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D3; ein Gate auf diesen Wert ist STAGED (din1989_2-G-6 — heute prüft kein Gate die Gl. 4).', 'imported_unverified', 'V_{\text {Prüf }} \geq Q_{\mathrm{Zu}, \max } \times 90 \tag{4}', 'derived', NULL, NULL, 'DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'v_pruef_leist_ok') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'v_pruef_trenn_ok', 'V_Prüf (Trennwirkung) ≥ Q_Zu,max × 180 (1 = erfüllt, 0 = unterschritten)', 'number', NULL, false, '§6.5.1, Gl. 6', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D4; Gate STAGED (din1989_2-G-6).', 'imported_unverified', 'V_{\text {Prüf }} \geq Q_{\text {Zu,max }} \times 180 \tag{6}', 'derived', NULL, NULL, 'DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'v_pruef_trenn_ok') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
