INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'V_pruefmedium_l', 'Volumen des Prüfmediums (Tab. 3 gilt je 1000 Liter)', 'number', 'l', false, '§6.5.1, Tab. 3', 'Plan 3: Bezugsvolumen der Prüfstoff-Sollmassen (masse_soll = Konzentration × Volumen je Zeile des Registers pruefstoffe).', 'imported_unverified', 'Die Menge, Masse und Konzentration des einzelnen Prüfstoffes je 1000 Liter Prüfmedium muss Tabelle 3 entsprechen. — Tabelle 3 - Prüfstoffe je 1000 Liter Prüfmedium', 'scalar', NULL, NULL, 'DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'V_pruefmedium_l') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'pruefstoffe', 'Prüfstoffe nach Tab. 3 — Massenbilanz (Σ zugegeben / Speicher / Verwurf)', 'json', NULL, false, '§6.5.1, §6.5.2, §6.5.3, Tab. 3', 'Plan 3: Zeilen je Prüfstoff (Tab. 3 → Konzentration und Stückzahl gefüllt, Sollmasse = Konzentration × Prüfmedium, gefundene Massen im Speicher und — bei Typ C — im Verwurf); Σ → m_ges_festst_calc / m_sp_verunr_calc / m_verw_calc (DIN-1989-2-03-D10 … D12), Trennwirkung nach Gl. 7 / 8 / 9 → eta_rueck_calc / eta_verw_calc / eta_c_calc (-D13 … D15); Umstellung der Gl. 7–9 auf die Register-Summen STAGED (din1989_2-R-2, D-10 … D-12).', 'imported_unverified', 'Die Filtertrennwirkung ist für Filter mit Zulaufnennweiten $\leq$ DN 200 nachzuweisen. Bei der Prüfung nach 6.5 sind möglichst viele Fremdstoffe, die dem Filter zufließen, vor dem Zufluss in den Speicher zurückzuhalten oder abzuleiten. — Die Menge, Masse und Konzentration des einzelnen Prüfstoffes je 1000 Liter Prüfmedium muss Tabelle 3 entsprechen. — Tabelle 3 - Prüfstoffe je 1000 Liter Prüfmedium — \hline \multicolumn{4}{|l|}{${ }^{\mathrm{a}}$ Die LDPE-Folie geht fiktiv mit $10 \mathrm{~g} /$ Stück in die Massenbilanz ein.} \\ — Nicht abgetrennte Prüfstoffe sind am Filterablauf mit einem Drahtsieb mit einer Nennmaschenweite von $250 \mu \mathrm{~m}$ nach DIN ISO 3310-1, das zur Nasssiebung geeignet ist, aufzufangen, zu trocknen und zu wägen. Bei Filtern Typ C ist der Verwurf (siehe 3.17) in gleicher Weise zu ermitteln. Maßgebend sind jeweils die Mengen- bzw. Masseanteile der gefundenen Zusätze. — Die Filtertrennwirkung ist als Quotient aus zurückgehaltenen Prüfstoffen bzw. abgeleiteten Prüfstoffen zur Gesamtfeststoffmasse je nach Filtertyp zu ermitteln.', 'register', '{"title":"Prüfstoffe (Tab. 3) — Massenbilanz","subtitle":"§6.5.1 / §6.5.2 — je Prüfstoff Sollmasse aus Tab. 3 × Prüfmedium, gefundene Masse im Speicher (Sp.verunr) und bei Typ C im Verwurf","add_label":"+ Prüfstoff","placement":"section","columns":[{"key":"stoff","label":"Prüfstoff (Tab. 3)","type":"lookup_key","required":true,"lookup":{"table_code":"TAB3"}},{"key":"konz","label":"Massenkonzentration (Tab. 3)","type":"lookup_value","unit":"g/l","lookup":{"table_code":"TAB3","key_column":"stoff","value":"konzentration_g_l"}},{"key":"stueck","label":"Menge je 1000 l (Tab. 3)","type":"lookup_value","unit":"Stück","lookup":{"table_code":"TAB3","key_column":"stoff","value":"stueck"}},{"key":"fussnote","label":"Fußnote","type":"lookup_value","lookup":{"table_code":"TAB3","key_column":"stoff","value":"fussnote"}},{"key":"masse_soll","label":"Sollmasse zugegeben","type":"derived","expr":"konz * V_pruefmedium_l","unit":"g"},{"key":"stueck_soll","label":"Stück zugegeben","type":"derived","expr":"if(stueck IS NULL, 0, stueck * V_pruefmedium_l / 1000)"},{"key":"masse_speicher_g","label":"gefunden im Speicher (Sp.verunr)","type":"number","unit":"g","required":true,"min":0,"aria_label":"im Speicher gefundene Masse"},{"key":"masse_verwurf_g","label":"gefunden im Verwurf (Typ C)","type":"number","unit":"g","min":0,"visible_when":"filtertyp == ''typ_c''","aria_label":"im Verwurf gefundene Masse"}],"footer":["m_ges_festst_calc","m_sp_verunr_calc","m_verw_calc","eta_rueck_calc","eta_verw_calc","eta_c_calc"],"note":"Nicht abgetrennte Prüfstoffe sind am Filterablauf mit einem Drahtsieb mit einer Nennmaschenweite von $250 \\mu \\mathrm{~m}$ nach DIN ISO 3310-1, das zur Nasssiebung geeignet ist, aufzufangen, zu trocknen und zu wägen. Bei Filtern Typ C ist der Verwurf (siehe 3.17) in gleicher Weise zu ermitteln. Maßgebend sind jeweils die Mengen- bzw. Masseanteile der gefundenen Zusätze. LDPE-Folie: gefundene Stücke × 10 g eintragen (Fußnote a, Tab. 3)."}'::jsonb, NULL, 'DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'pruefstoffe') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'm_ges_festst_calc', 'Σ zugegebene Prüfstoffe (Σ ges.Festst, aus Tab. 3 × Prüfmedium)', 'number', 'g', false, '§6.5.1, Tab. 3, Gl. 7', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D10 (sum_rows über masse_soll); Zwilling zum Skalar m_ges_festst (din1989_2-D-10).', 'imported_unverified', 'Die Menge, Masse und Konzentration des einzelnen Prüfstoffes je 1000 Liter Prüfmedium muss Tabelle 3 entsprechen. — \eta_{\text {Rück,A,B }}=\frac{\sum_{\text {ges.Festst }}-\sum_{\text {Sp.verunr }}}{\sum_{\text {ges.Festst }}} \tag{7}', 'derived', NULL, NULL, 'DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'm_ges_festst_calc') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
