SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'm_sp_verunr_calc', 'Σ im Speicher gefundene Prüfstoffe (Σ Sp.verunr)', 'number', 'g', false, '§6.5.2, Gl. 7', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D11 (sum_rows über masse_speicher_g); Zwilling zum Skalar m_sp_verunr (din1989_2-D-11).', 'imported_unverified', 'Nicht abgetrennte Prüfstoffe sind am Filterablauf mit einem Drahtsieb mit einer Nennmaschenweite von $250 \mu \mathrm{~m}$ nach DIN ISO 3310-1, das zur Nasssiebung geeignet ist, aufzufangen, zu trocknen und zu wägen. Bei Filtern Typ C ist der Verwurf (siehe 3.17) in gleicher Weise zu ermitteln. Maßgebend sind jeweils die Mengen- bzw. Masseanteile der gefundenen Zusätze. — \eta_{\text {Rück,A,B }}=\frac{\sum_{\text {ges.Festst }}-\sum_{\text {Sp.verunr }}}{\sum_{\text {ges.Festst }}} \tag{7}', 'derived', NULL, NULL, 'DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'm_sp_verunr_calc') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'm_verw_calc', 'Σ im Verwurf gefundene Prüfstoffe (Σ Verw, Typ C)', 'number', 'g', false, '§6.5.2, §6.5.3.2, Gl. 8', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D12 (sum_rows über masse_verwurf_g, leere Zellen zählen 0); Zwilling zum Skalar m_verw (din1989_2-D-12).', 'imported_unverified', 'Nicht abgetrennte Prüfstoffe sind am Filterablauf mit einem Drahtsieb mit einer Nennmaschenweite von $250 \mu \mathrm{~m}$ nach DIN ISO 3310-1, das zur Nasssiebung geeignet ist, aufzufangen, zu trocknen und zu wägen. Bei Filtern Typ C ist der Verwurf (siehe 3.17) in gleicher Weise zu ermitteln. Maßgebend sind jeweils die Mengen- bzw. Masseanteile der gefundenen Zusätze. — \eta_{\text {Verw }}=\frac{\sum_{\text {Verw }}}{\sum_{\text {ges.Festst }}} \tag{8}', 'derived', NULL, NULL, 'filtertyp == ''typ_c'' AND DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'm_verw_calc') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
