SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'eta_rueck_calc', 'η_Rück = (Σ ges.Festst − Σ Sp.verunr) / Σ ges.Festst (Gl. 7)', 'number', NULL, false, '§6.5.3.1, Gl. 7', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D13 über das Register pruefstoffe — die Trennwirkung der Typen A / B (Gl. 7) und der Speicher-Anteil der Typ-C-Bilanz (Gl. 9); Zwilling zu eta_Rueck_AB (Umstellung STAGED din1989_2-R-2).', 'imported_unverified', 'Für die Filter Typ A und Typ B ist die Filtertrennwirkung $\eta_{\text {Rück, } \mathrm{A}, \mathrm{B}}$ zu ermitteln aus: — \eta_{\text {Rück,A,B }}=\frac{\sum_{\text {ges.Festst }}-\sum_{\text {Sp.verunr }}}{\sum_{\text {ges.Festst }}} \tag{7}', 'derived', NULL, NULL, 'DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'eta_rueck_calc') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
