SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'eta_c_calc', 'η_C = 0,5 (Σ ges.Festst − Σ Sp.verunr + Σ Verw) / Σ ges.Festst (Gl. 9, Typ C)', 'number', NULL, false, '§6.5.3.2, Gl. 9', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D15 über das Register pruefstoffe; Zwilling zu eta_C (Gl. 9).', 'imported_unverified', 'Filter vom Typ C verfügen über kein planmäßiges Rückhaltevolumen. Die Prüfung wird gegenüber Typ A und Typ B um die Wirksamkeit des Verwurfes von Fremdstoffen in die Abflussleitung (so genannte Schmutzfrachttrennung) ergänzt. — \eta_{\mathrm{C}}=0,5\left(\eta_{\text {Rück }}+\eta_{\text {Verw }}\right)=0,5 \frac{\Sigma_{\text {ges.Festst }}-\Sigma_{\text {Sp. veruur }}+\Sigma_{\text {Verw }}}{\Sigma_{\text {ges.Festst }}} \tag{9}', 'derived', NULL, NULL, 'filtertyp == ''typ_c'' AND DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'eta_c_calc') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
