SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'filtertrennwirkung_code_ab', 'Filtertrennwirkung Typ A/B ≥ 0,7 (1 = nachgewiesen, 0 = unterschritten)', 'number', NULL, false, '§5.5, §6.5.3.1', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D16 (η_Rück nach Gl. 7 ≥ 0,7); abgeleiteter Zwilling zum manuellen Boolean filtertrennwirkung_nachgewiesen — Umstellung von CR-08 STAGED (din1989_2-D-2 / G-4).', 'imported_unverified', 'Hinsichtlich der Abtrennung von Fremdstoffen müssen diese Filter einen Wirkungsgrad von mindestens 0,7 erreichen (siehe 6.5.3). — \eta_{\text {Rück,A,B }}=\frac{\sum_{\text {ges.Festst }}-\sum_{\text {Sp.verunr }}}{\sum_{\text {ges.Festst }}} \tag{7}', 'derived', NULL, NULL, 'filtertyp IN {''typ_a'', ''typ_b''} AND DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'filtertrennwirkung_code_ab') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
