SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'filtertrennwirkung_code_c', 'Filtertrennwirkung Typ C ≥ 0,7 (1 = nachgewiesen, 0 = unterschritten)', 'number', NULL, false, '§5.5, §6.5.3.2', 'Plan 3: Ausgabe der Gleichung DIN-1989-2-03-D17 (η_C nach Gl. 9 ≥ 0,7); Zwilling zu filtertrennwirkung_nachgewiesen für Typ C (din1989_2-D-2 / G-4).', 'imported_unverified', 'Hinsichtlich der Abtrennung von Fremdstoffen müssen diese Filter einen Wirkungsgrad von mindestens 0,7 erreichen (siehe 6.5.3). — \eta_{\mathrm{C}}=0,5\left(\eta_{\text {Rück }}+\eta_{\text {Verw }}\right)=0,5 \frac{\Sigma_{\text {ges.Festst }}-\Sigma_{\text {Sp. veruur }}+\Sigma_{\text {Verw }}}{\Sigma_{\text {ges.Festst }}} \tag{9}', 'derived', NULL, NULL, 'filtertyp == ''typ_c'' AND DN <= 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'filtertrennwirkung_code_c') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
