INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'hersteller_verfahren_dokumentiert', 'DN > 200: Hersteller hat Filtertrennwirkung und hydraulischen Wirkungsgrad des dauerbelasteten Systems angegeben und das Ermittlungsverfahren nachvollziehbar dokumentiert (§5.1, §6.1)', 'boolean', NULL, false, '§5.1, §6.1', 'Plan 3: Bestätigung für Filter > DN 200 (kein genormtes Prüfverfahren für 6.4.6 / 6.5); ein Gate IF DN > 200 THEN … ist STAGED (din1989_2-G-4).', 'imported_unverified', 'Für Filter mit Zulaufnennweite > DN 200 gibt es für die Anforderung Filtertrennwirkung und hydraulischer Wirkungsgrad des dauerbelasteten Systems zur Zeit kein genormtes Prüfverfahren. Der Hersteller muss diese Werte angeben und nachvollziehbar dokumentieren, wie er diese Werte ermittelt hat. Dem Auftraggeber und den Prüfstellen ist das Verfahren zur Ermittlung der angegebenen Werte auf Verlangen vorzulegen. Alle anderen Anforderungen müssen DIN 1989-2 entsprechen. — Für Filter mit Zulaufnennweite > DN200 sind die Prüfung des hydraulischen Wirkungsgrads des dauerbelasteten Systems nach 6.4.6 und der Filtertrennwirkung nach 6.5 nicht geeignet. In diesen Fällen ist vom Hersteller nachvollziehbar zu dokumentieren, wie er die von ihm angegebenen Werte ermittelt hat (siehe 5.1).', 'attestation', NULL, NULL, 'DN > 200', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'hersteller_verfahren_dokumentiert') AND w.code = 'DIN-1989-2-03' AND s.code = 'DIN-1989-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'A'), 'kennzeichnung', 'Vorhandene Kennzeichnungsangaben (§7 a–i)', 'json', NULL, false, '§7', 'Plan 3: Mehrfachauswahl über die neun gedruckten Kennzeichnungspositionen a)–i); Zwilling zum manuellen Boolean kennzeichnung_vollstaendig (CR-14) — Umstellung STAGED (din1989_2-D-1); Position g) gilt nur bei Kunststoff.', 'imported_unverified', 'Regenwasserfilter nach dieser Norm sind deutlich sichtbar und dauerhaft wie folgt zu kennzeichnen mit:', 'select_many', '{"title":"Kennzeichnung (§7, a–i)","subtitle":"Regenwasserfilter nach dieser Norm sind deutlich sichtbar und dauerhaft zu kennzeichnen mit:","note":"g) Werkstoffbezeichnung (nur bei Kunststoff nach DIN EN ISO 1043-1);"}'::jsonb, NULL, NULL, '[{"value":"a_nummer_norm","label_de":"a) Nummer dieser Norm;","order_index":0},{"value":"b_hersteller","label_de":"b) Name und/oder Zeichen des Herstellers;","order_index":1},{"value":"c_typ","label_de":"c) Typ;","order_index":2},{"value":"d_nenngroesse","label_de":"d) Nenngröße des Zu- und Ablaufs;","order_index":3},{"value":"e_fliessrichtung","label_de":"e) Fließrichtung;","order_index":4},{"value":"f_filtertrennwirkung","label_de":"f) Filtertrennwirkung nach 6.5.3;","order_index":5},{"value":"g_werkstoffbezeichnung","label_de":"g) Werkstoffbezeichnung (nur bei Kunststoff nach DIN EN ISO 1043-1);","order_index":6},{"value":"h_herstelldatum","label_de":"h) Herstelldatum;","order_index":7},{"value":"i_ueberwachende_stelle","label_de":"i) Zeichen der überwachenden Stelle.","order_index":8}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'kennzeichnung') AND w.code = 'DIN-1989-2-04' AND s.code = 'DIN-1989-2';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'werkstoff_filterelement == ''kunststoff''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'werkstoffbezeichnung' AND w.code = 'DIN-1989-2-04' AND s.code = 'DIN-1989-2' AND f.active;
COMMIT;
